set -eu
hostname -s; date -u +%TZ
F=/scratch/jjyeung/orch_n30/tree_rebuild10_w/w32frm
test ! -e $F/n_go || { echo "w32frm/n_go exists; stop"; exit 3; }
mkdir -p $F/in/k $F/in/b
echo '' | base64 -d > $F/in/k/j.json; echo '' | base64 -d > $F/in/b/pf.py; echo '' | base64 -d > $F/in/b/pl.py
echo '' | base64 -d > $F/b32.py
sha256sum $F/in/k/j.json $F/in/b/pf.py $F/in/b/pl.py $F/b32.py
cd $F && timeout 300 nice -n 10 python3 -I -B $F/b32.py > $F/build.log 2>&1; echo rc=$?; tail -c 3500 $F/build.log
